/* @autogenerated */
import { Component, inject } from '@angular/core';
import { ThemeAsset } from 'app/features/template/theme-asset/model/theme-asset.model';
import { ThemeAssetRepository } from 'app/features/template/theme-asset/repository/theme-asset-repository.service';
import { ConfirmAction } from 'app/shared/toolkit/action/confirm-action';

@Component({ selector: 'theme-asset-view-enable-action', standalone: false, template: '' })
export class ThemeAssetViewEnableActionComponent extends ConfirmAction<ThemeAsset> {
  readonly name = 'enable';
  protected readonly scope = 'template/theme-asset';
  protected readonly repository = inject(ThemeAssetRepository);

  protected override appliesTo(items: ThemeAsset[]) {
    return items.every((item) => !item.enabled);
  }

  protected execute([item]: ThemeAsset[]) {
    return this.repository.enable(item.uid);
  }
}
